const NAMES: Record<string, [string, string]> = {
  "go": ["go", "light-dark(#00ADD8, #00ADD8)"],
  "hashicorp vault": ["hashicorp", "var(--text)"],
  "nginx": ["nginx", "light-dark(#009639, #3DBE6B)"],
  "apache httpd": ["apache", "light-dark(#D22128, #F0565C)"],
  "apache tomcat": ["apachetomcat", "light-dark(#B38600, #F8DC75)"],
  "apache-coyote": ["apachetomcat", "light-dark(#B38600, #F8DC75)"],
  "caddy": ["caddy", "light-dark(#1F88C0, #4FB0E3)"],
  "traefik": ["traefikproxy", "light-dark(#24A1C1, #4CC4E2)"],
  "envoy": ["envoyproxy", "light-dark(#AC6199, #D18BC0)"],
  "jetty": ["eclipsejetty", "light-dark(#FC390E, #FF6A47)"],
  "kestrel": ["dotnet", "light-dark(#512BD4, #9780E5)"],
  "asp.net": ["dotnet", "light-dark(#512BD4, #9780E5)"],
  "gunicorn": ["gunicorn", "light-dark(#499848, #6FC46E)"],
  "cloudflare": ["cloudflare", "light-dark(#F38020, #F38020)"],
  "amazons3": ["amazons3", "light-dark(#569A31, #7CC455)"],
  "akamaighost": ["akamai", "light-dark(#0096D6, #38B6EC)"],
  "php": ["php", "light-dark(#777BB4, #A3A6D6)"],
  "java": ["openjdk", "var(--text)"],
  "python": ["python", "light-dark(#3776AB, #6CA3D9)"],
  "node.js": ["nodedotjs", "light-dark(#5FA04E, #7FC56C)"],
  "express": ["express", "var(--text)"],
  "spring boot": ["springboot", "light-dark(#6DB33F, #8BD35E)"],
  "django": ["django", "light-dark(#092E20, #44B78B)"],
  "laravel": ["laravel", "light-dark(#FF2D20, #FF5A50)"],
  "next.js": ["nextdotjs", "var(--text)"],
  "flask": ["flask", "light-dark(#3BABC3, #5CC8DE)"],
  "codeigniter": ["codeigniter", "light-dark(#EF4223, #FF6B50)"],
  "mysql": ["mysql", "light-dark(#4479A1, #6FA3D2)"],
  "mariadb": ["mariadb", "light-dark(#003545, #C49A6C)"],
  "elasticsearch": ["elasticsearch", "light-dark(#005571, #00BFB3)"],
  "filezilla server": ["filezilla", "light-dark(#BF0000, #FF5A5A)"],
  "dovecot": ["dovecot", "light-dark(#54BCAB, #54BCAB)"],
};

// logo is the mark and colour for a piece of software, by the name the
// scanner gives it, or nothing when there's none.
export function logo(name: string): { path: string; color: string } | undefined {
  const found = NAMES[name.toLowerCase()];
  return found && { path: PATHS[found[0]], color: found[1] };
}
